class ClientNotConnected(Exception):
    pass


class ClientRequestFailed(Exception):
    pass


class ClientConnectionFailed(Exception):
    pass


class ClientAuthenticationFailed(Exception):
    pass


class FrameDecodingError(Exception):
    pass


class OutgoingFrameRejected(Exception):
    pass


class UnexpectedFrameReceived(Exception):

    def __eq__(self, other):
        return str(self) == str(other)

    def __ne__(self, other):
        return not self.__eq__(other)


class TimeoutExceeded(Exception):
    pass
